-- Register AI scale assessment as a selectable server plugin in the manager console.
SET @data_exists = (SELECT COUNT(*) FROM ai_model_provider WHERE id = 'SYSTEM_PLUGIN_AI_SCALE');
SET @sql = IF(@data_exists = 0,
    'INSERT INTO `ai_model_provider` (`id`, `model_type`, `provider_code`, `name`, `fields`, `sort`, `creator`, `create_date`, `updater`, `update_date`) VALUES (''SYSTEM_PLUGIN_AI_SCALE'', ''Plugin'', ''ai_scale_assessment'', ''AI量表评估'', JSON_ARRAY(JSON_OBJECT(''key'', ''base_url'', ''type'', ''string'', ''label'', ''量表服务地址'', ''default'', ''https://tongyimohe.cloud'', ''editing'', false, ''selected'', false), JSON_OBJECT(''key'', ''partner_token'', ''type'', ''string'', ''label'', ''Partner Token'', ''default'', '''', ''editing'', false, ''selected'', false), JSON_OBJECT(''key'', ''device_id_prefix'', ''type'', ''string'', ''label'', ''设备ID前缀'', ''default'', ''xiaozhi'', ''editing'', false, ''selected'', false), JSON_OBJECT(''key'', ''default_nickname'', ''type'', ''string'', ''label'', ''默认成员昵称'', ''default'', ''本人'', ''editing'', false, ''selected'', false), JSON_OBJECT(''key'', ''description'', ''type'', ''string'', ''label'', ''工具描述'', ''default'', ''当用户想做情绪、焦虑、注意力、发育、睡眠、行为相关筛查时调用。不要自行编造量表题目、分数或医学诊断。'', ''editing'', false, ''selected'', false)), 90, 0, NOW(), 0, NOW())',
    'SELECT ''SYSTEM_PLUGIN_AI_SCALE already exists, skip'' AS msg');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
